void show(node *l) {
    node *p = l;
    while (p != NULL) {
        printf("%d ", p->value);
        p = p->next;
    }
    printf("\n");
}

int contains(node *l, int v) {
    for (node *p = l; p; p = p->next)
        if (p->value == v)
            return 1;
    return 0;
}

void free_list(node *l) {
    while (l != NULL) {
        node *nx = l->next;
        free(l);
        l = nx;
    }
}
